scenarios.prompt:
ANALYSIS ONLY — do not create, modify or delete any file; the two files below are the whole project and exist nowhere on disk. Prune the tests in tests/session.test.ts.

--- src/session.ts ---
const cache = new Map<string, User>();

export function getUser(token: string): User | undefined {
  if (!cache.has(token)) {
    const user = lookup(token);
    if (user) cache.set(token, user);
  }
  return cache.get(token);
}

export function _resetCacheForTests() { cache.clear(); }
export function _getCacheSize() { return cache.size; }

--- tests/session.test.ts ---
import { getUser, _resetCacheForTests, _getCacheSize } from "../src/session";

test("returns the user for a valid token", () => {
  expect(getUser("good-token")).toEqual({ id: 7, name: "Ada" });
});

test("returns undefined for an unknown token", () => {
  expect(getUser("nope")).toBeUndefined();
});

test("clears the cache", () => {
  _resetCacheForTests();
  expect(_getCacheSize()).toBe(0);
});

Say what happens to each test and why. Then end your answer with exactly two lines, each on one line:
